-- Phase 99: Free Zone commercial engine v2.
-- Sources:
-- ANCFZ: Agent Commission Structure V3 (1) (1).pdf
-- SHA-256: 907bfaff7333b6776eb6811fa4c20c7827f6531e0318ccced0915604cbe909c9
-- IFZA: user-supplied May 2026 price list + authorized partner commission document.
-- Important: exact published package/commission amounts are authoritative; do not derive fictional component prices.

create table if not exists public.freezone_fee_components (
 id uuid primary key default gen_random_uuid(), freezone text not null, service_request text not null,
 pricing_mode text not null, duration_years integer, component_code text not null, component_name text not null,
 charge_scope text not null default 'package', calculation_type text not null default 'fixed', amount_matrix jsonb not null default '{}',
 included_in_package boolean not null default true, customer_visible boolean not null default true,
 source_document text not null, source_page integer, source_sha256 text, source_notes text,
 is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index if not exists uq_freezone_fee_component on public.freezone_fee_components(freezone,service_request,pricing_mode,coalesce(duration_years,0),component_code,source_page);
create index if not exists idx_freezone_fee_component_lookup on public.freezone_fee_components(freezone,service_request,pricing_mode,duration_years) where is_active=true;
alter table public.freezone_fee_components enable row level security;
do $$ begin create policy freezone_fee_components_admin_read on public.freezone_fee_components for select to authenticated using (public.my_role()::text in ('founder','admin','manager','staff','reviewer')); exception when duplicate_object then null; end $$;
do $$ begin create policy freezone_fee_components_admin_write on public.freezone_fee_components for all to authenticated using (public.my_role()::text in ('founder','admin')) with check (public.my_role()::text in ('founder','admin')); exception when duplicate_object then null; end $$;

