-- IFZA exact 1-year partner commission amounts supplied in the captured 2026 partner document.
insert into public.agent_commission_schedules(freezone,service_request,pricing_mode,duration_years,commission_type,tier_matrix,source_document,source_page,source_sha256,source_notes) values
('IFZA','new_registration','plan_a',1,'tiered_matrix','{"A":{"label":"Plan A — 20% commission","rate":20,"amounts":[2600,3000,3400,3800,4200],"partner_payable":[10300,11900,13500,15100,16700]}}','IFZA PRICE LIST & COMMISSION PLANS FOR AUTHORIZED PARTNERS FOR 2026',1,'USER-SUPPLIED-MAY-2026-IFZA','Exact published amounts; 4+ is a source band.'),
('IFZA','new_registration','plan_b',1,'tiered_matrix','{"B":{"label":"Plan B — 30% commission","rate":30,"amounts":[3900,4500,5100,5700,6300],"partner_payable":[9000,10400,11800,13200,14600]}}','IFZA PRICE LIST & COMMISSION PLANS FOR AUTHORIZED PARTNERS FOR 2026',1,'USER-SUPPLIED-MAY-2026-IFZA','Exact published amounts; annual-volume trigger for choosing Plan A/B was not captured, so none is invented.')
on conflict (freezone,service_request,pricing_mode,coalesce(duration_years,0),source_page) do update set tier_matrix=excluded.tier_matrix,source_notes=excluded.source_notes,is_active=true,updated_at=now();

alter table public.agent_commission_schedules add column if not exists volume_rules jsonb;
update public.agent_commission_schedules set volume_rules='{"35":{"min":1,"max":10},"40":{"min":11,"max":20},"45":{"min":21,"max":30},"50":{"min":31,"max":350},"55":{"min":351,"max":null}}' where freezone='ANCFZ' and service_request='new_registration' and commission_type='tiered_matrix';
revoke all on public.freezone_fee_components from anon;
revoke all on public.agent_commission_schedules from anon;
